PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS regions ( code TEXT PRIMARY KEY, name TEXT NOT NULL, country TEXT NOT NULL, map_x REAL NOT NULL, map_y REAL NOT NULL, position INTEGER NOT NULL DEFAULT 0, ping_url TEXT, ping_label TEXT );
CREATE TABLE IF NOT EXISTS component_groups ( id TEXT PRIMARY KEY NOT NULL CHECK (length(id) = 26 AND id GLOB '[0-7]*' AND id NOT GLOB '*[^0-9A-HJKMNP-TV-Z]*'), name TEXT NOT NULL, position INTEGER NOT NULL DEFAULT 0 );
CREATE TABLE IF NOT EXISTS components ( id TEXT PRIMARY KEY NOT NULL CHECK (length(id) = 26 AND id GLOB '[0-7]*' AND id NOT GLOB '*[^0-9A-HJKMNP-TV-Z]*'), group_id TEXT NOT NULL REFERENCES component_groups(id), name TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', lifecycle TEXT NOT NULL DEFAULT 'active' CHECK (lifecycle IN ('active', 'planned')), position INTEGER NOT NULL DEFAULT 0 );
CREATE TABLE IF NOT EXISTS endpoints ( id TEXT PRIMARY KEY NOT NULL CHECK (length(id) = 26 AND id GLOB '[0-7]*' AND id NOT GLOB '*[^0-9A-HJKMNP-TV-Z]*'), component_id TEXT NOT NULL REFERENCES components(id), region_code TEXT REFERENCES regions(code), cluster TEXT NOT NULL, provider TEXT NOT NULL CHECK (provider IN ('fly', 'oci', 'cloudflare', 'other')), url TEXT NOT NULL, headers TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(headers)), enabled INTEGER NOT NULL DEFAULT 1 CHECK (enabled IN (0, 1)), position INTEGER NOT NULL DEFAULT 0, expect_status TEXT NOT NULL DEFAULT '2xx', keyword TEXT, assertions TEXT NOT NULL DEFAULT '[]' CHECK (json_valid(assertions)), extract TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(extract)), indirect INTEGER NOT NULL DEFAULT 0 CHECK (indirect IN (0, 1)), kind TEXT NOT NULL DEFAULT 'http' CHECK (kind IN ('http', 'canary')), probe TEXT CHECK (probe IN ('health', 'documents', 'management')), pending_status INTEGER CHECK (pending_status BETWEEN 100 AND 599), blocked_status INTEGER CHECK (blocked_status BETWEEN 100 AND 599) );
CREATE TABLE IF NOT EXISTS incidents ( id TEXT PRIMARY KEY NOT NULL CHECK (length(id) = 26 AND id GLOB '[0-7]*' AND id NOT GLOB '*[^0-9A-HJKMNP-TV-Z]*'), kind TEXT NOT NULL DEFAULT 'incident' CHECK (kind IN ('incident', 'warning', 'maintenance')), title TEXT NOT NULL, status TEXT NOT NULL CHECK (status IN ('investigating', 'identified', 'monitoring', 'resolved', 'scheduled', 'in_progress', 'completed')), impact TEXT NOT NULL CHECK (impact IN ('none', 'minor', 'major', 'critical')), source TEXT NOT NULL DEFAULT 'manual' CHECK (source IN ('manual', 'auto')), auto_key TEXT REFERENCES components(id), operator_touched INTEGER NOT NULL DEFAULT 0 CHECK (operator_touched IN (0, 1)), scheduled_start TEXT, scheduled_end TEXT, created_at TEXT NOT NULL DEFAULT (datetime('now')), updated_at TEXT NOT NULL DEFAULT (datetime('now')), resolved_at TEXT, CHECK (kind != 'maintenance' OR (scheduled_start IS NOT NULL AND scheduled_end IS NOT NULL)) );
CREATE TABLE IF NOT EXISTS incident_updates ( id TEXT PRIMARY KEY NOT NULL CHECK (length(id) = 26 AND id GLOB '[0-7]*' AND id NOT GLOB '*[^0-9A-HJKMNP-TV-Z]*'), incident_id TEXT NOT NULL REFERENCES incidents(id) ON DELETE CASCADE, status TEXT NOT NULL, body TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT (datetime('now')) );
CREATE TABLE IF NOT EXISTS incident_components ( incident_id TEXT NOT NULL REFERENCES incidents(id) ON DELETE CASCADE, component_id TEXT NOT NULL REFERENCES components(id) ON DELETE CASCADE, PRIMARY KEY (incident_id, component_id) ) WITHOUT ROWID;
CREATE TABLE IF NOT EXISTS probe_samples ( endpoint_id TEXT NOT NULL REFERENCES endpoints(id) ON DELETE CASCADE, at TEXT NOT NULL, state TEXT NOT NULL CHECK (state IN ('operational', 'degraded', 'partial_outage', 'major_outage', 'none')), ok INTEGER NOT NULL, total INTEGER NOT NULL, latency_ms INTEGER, results TEXT NOT NULL CHECK (json_valid(results)), "values" TEXT, PRIMARY KEY (endpoint_id, at) ) WITHOUT ROWID;
CREATE TABLE IF NOT EXISTS probe_hours ( endpoint_id TEXT NOT NULL REFERENCES endpoints(id) ON DELETE CASCADE, hour TEXT NOT NULL, vantage TEXT NOT NULL, checks INTEGER NOT NULL, failures INTEGER NOT NULL, degraded INTEGER NOT NULL DEFAULT 0, latency_sum INTEGER NOT NULL, latency_max INTEGER NOT NULL, hist TEXT NOT NULL DEFAULT '[]', PRIMARY KEY (endpoint_id, hour, vantage) ) WITHOUT ROWID;
CREATE TABLE IF NOT EXISTS probe_days ( endpoint_id TEXT NOT NULL REFERENCES endpoints(id) ON DELETE CASCADE, day TEXT NOT NULL, vantage TEXT NOT NULL, checks INTEGER NOT NULL, failures INTEGER NOT NULL, degraded INTEGER NOT NULL, latency_sum INTEGER NOT NULL, latency_max INTEGER NOT NULL, hist TEXT NOT NULL, PRIMARY KEY (endpoint_id, day, vantage) ) WITHOUT ROWID;
CREATE TABLE IF NOT EXISTS deploys ( endpoint_id TEXT NOT NULL REFERENCES endpoints(id) ON DELETE CASCADE, version TEXT NOT NULL, detected_at TEXT NOT NULL, PRIMARY KEY (endpoint_id, detected_at) ) WITHOUT ROWID;
CREATE TABLE IF NOT EXISTS vantages ( code TEXT PRIMARY KEY, colo TEXT, seen_at TEXT NOT NULL );
CREATE TABLE IF NOT EXISTS tls_certs ( host TEXT PRIMARY KEY, not_after TEXT, issuer TEXT, checked_at TEXT NOT NULL, error TEXT );
CREATE TABLE IF NOT EXISTS subscribers ( id TEXT PRIMARY KEY NOT NULL CHECK (length(id) = 26 AND id GLOB '[0-7]*' AND id NOT GLOB '*[^0-9A-HJKMNP-TV-Z]*'), channel TEXT NOT NULL CHECK (channel IN ('email', 'webhook')), target TEXT NOT NULL, flavor TEXT NOT NULL DEFAULT 'email' CHECK (flavor IN ('email', 'discord', 'slack', 'generic')), components TEXT NOT NULL DEFAULT '[]' CHECK (json_valid(components)), confirmed_at TEXT, created_at TEXT NOT NULL DEFAULT (datetime('now')), UNIQUE (channel, target) );
CREATE TABLE IF NOT EXISTS outbox ( id TEXT PRIMARY KEY NOT NULL CHECK (length(id) = 26 AND id GLOB '[0-7]*' AND id NOT GLOB '*[^0-9A-HJKMNP-TV-Z]*'), subscriber_id TEXT NOT NULL REFERENCES subscribers(id) ON DELETE CASCADE, kind TEXT NOT NULL CHECK (kind IN ('confirm', 'update')), update_id TEXT REFERENCES incident_updates(id) ON DELETE CASCADE, attempts INTEGER NOT NULL DEFAULT 0, next_attempt_at TEXT NOT NULL DEFAULT (datetime('now')), sent_at TEXT, claim TEXT, last_error TEXT, created_at TEXT NOT NULL DEFAULT (datetime('now')), UNIQUE (subscriber_id, update_id) );
CREATE INDEX IF NOT EXISTS endpoints_component_idx ON endpoints(component_id, position);
CREATE INDEX IF NOT EXISTS endpoints_region_idx ON endpoints(region_code, position);
CREATE INDEX IF NOT EXISTS incidents_created_at_idx ON incidents(created_at DESC);
CREATE INDEX IF NOT EXISTS incidents_status_idx ON incidents(status, resolved_at);
CREATE INDEX IF NOT EXISTS incidents_maintenance_idx ON incidents(kind, scheduled_end);
CREATE UNIQUE INDEX IF NOT EXISTS incidents_auto_open_idx ON incidents(auto_key) WHERE auto_key IS NOT NULL AND status NOT IN ('resolved', 'completed');
CREATE INDEX IF NOT EXISTS incident_updates_incident_idx ON incident_updates(incident_id, created_at);
CREATE INDEX IF NOT EXISTS incident_components_component_idx ON incident_components(component_id);
CREATE INDEX IF NOT EXISTS outbox_due_idx ON outbox(sent_at, next_attempt_at);
